(function () {
  'use strict';

  /* 用户开启“减少动态效果”时，关闭雪花与所有装饰动画 */
  var reduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  /* =========================================================
     2. 地图装饰层（仅在 Dashboard 页面生效）
        - 经纬网：按地图真实投影逐格绘制，随缩放/拖动重绘
        - 南半球强调：极圈虚线 + 光晕，视口进入南半球时自动出现
        - GPS 扫描：扫描线、雷达扫掠、扩散光圈跟随真实定位点
        - 所有装饰层 pointer-events:none，不影响拖拽与缩放
  ========================================================= */
  var graticule = document.getElementById('mapGraticule');
  var radar = document.querySelector('.map-radar');
  var rings = document.querySelector('.gps-rings');
  var core = document.querySelector('.gps-core');
  var mapDpr = Math.min(window.devicePixelRatio || 1, 1.5);
  var rafPending = false;

  /* 画布尺寸对齐容器 */
  function fitCanvas() {
    if (!graticule) return;
    var box = graticule.parentElement;
    var w = box.clientWidth;
    var h = box.clientHeight;
    graticule.width = Math.round(w * mapDpr);
    graticule.height = Math.round(h * mapDpr);
    graticule.style.width = w + 'px';
    graticule.style.height = h + 'px';
  }

  /* 两点距离 */
  function dist(a, b) {
    return Math.sqrt((a.x - b.x) * (a.x - b.x) + (a.y - b.y) * (a.y - b.y));
  }

  /* 绘制一条折线 */
  function strokePath(ctx, pts, alpha, dash) {
    if (!pts || pts.length < 2) return;
    ctx.beginPath();
    ctx.moveTo(pts[0].x, pts[0].y);
    for (var i = 1; i < pts.length; i++) ctx.lineTo(pts[i].x, pts[i].y);
    ctx.strokeStyle = 'rgba(140,234,255,' + alpha + ')';
    ctx.lineWidth = 1;
    ctx.setLineDash(dash || []);
    ctx.stroke();
    ctx.setLineDash([]);
  }

  /* 在路径上寻找一个可见点，用于绘制经纬度标注 */
  function findLabelPoint(pts, w, h, preferBottom) {
    for (var i = 0; i < pts.length; i++) {
      var p = pts[i];
      if (p.x >= 12 && p.x <= w - 46 && p.y >= 10 && p.y <= h - 10) return p;
    }
    if (preferBottom) {
      for (var j = 0; j < pts.length; j++) {
        var q = pts[j];
        if (q.x >= 12 && q.x <= w - 12 && q.y >= h - 12 && q.y <= h + 60) return q;
      }
    }
    return null;
  }

  /* 经纬网：步长随缩放级别自适应，保证任何缩放下网格都清晰可见 */
  function drawGraticule(map, ctx, w, h) {
    ctx.clearRect(0, 0, w, h);
    /* 底层蓝图网格：固定像素间距铺满整个地图容器，四边完整连续 */
    var gstep = 48;
    ctx.strokeStyle = 'rgba(140,234,255,.055)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (var gx = 0; gx <= w; gx += gstep) { ctx.moveTo(gx, 0); ctx.lineTo(gx, h); }
    for (var gy = 0; gy <= h; gy += gstep) { ctx.moveTo(0, gy); ctx.lineTo(w, gy); }
    ctx.stroke();
    ctx.strokeStyle = 'rgba(140,234,255,.04)';
    ctx.beginPath();
    for (var gk = -h; gk <= w; gk += gstep) {
      var gx1 = gk >= 0 ? gk : 0;
      var gy1 = gk >= 0 ? 0 : -gk;
      var gx2, gy2;
      if (w - gk <= h) { gx2 = w; gy2 = w - gk; } else { gx2 = gk + h; gy2 = h; }
      ctx.moveTo(gx1, gy1); ctx.lineTo(gx2, gy2);
    }
    ctx.stroke();
    var b = map.getBounds();
    var z = map.getZoom();
    var baseStep = z >= 10 ? 0.25 : z >= 8 ? 0.5 : z >= 6 ? 1 : z >= 4 ? 5 : 10;

    /* 纬线（横向） */
    var latStart = Math.ceil(b.getSouth() / baseStep) * baseStep;
    for (var lat = latStart; lat <= b.getNorth(); lat += baseStep) {
      var major = (Math.abs(lat % (baseStep * 5)) < baseStep / 2) || (Math.abs(lat) % 30 === 0);
      var pts = [];
      var lonSample = Math.max((b.getEast() - b.getWest()) / 8, 0.05);
      for (var lon = b.getWest(); lon <= b.getEast(); lon += lonSample) {
        pts.push(map.latLngToContainerPoint([lat, lon]));
      }
      strokePath(ctx, pts, major ? 0.30 : 0.15);
      /* 主纬线标注，如 75°S */
      if (major && Math.abs(lat) % 5 === 0) {
        var lp = findLabelPoint(pts, w, h, false);
        if (lp) {
          ctx.fillStyle = 'rgba(140,234,255,.5)';
          ctx.font = '8px "Segoe UI", sans-serif';
          ctx.fillText(Math.abs(lat) + '°' + (lat < 0 ? 'S' : 'N'), lp.x + 4, lp.y - 3);
        }
      }
    }

    /* 经线（纵向） */
    var lonStart = Math.ceil(b.getWest() / baseStep) * baseStep;
    for (var lon2 = lonStart; lon2 <= b.getEast(); lon2 += baseStep) {
      var major2 = (Math.abs(lon2 % (baseStep * 5)) < baseStep / 2) || (Math.abs(lon2) % 60 === 0);
      var pts2 = [];
      var latSample = Math.max((b.getNorth() - b.getSouth()) / 8, 0.05);
      for (var lat2 = b.getSouth(); lat2 <= b.getNorth(); lat2 += latSample) {
        pts2.push(map.latLngToContainerPoint([lat2, lon2]));
      }
      strokePath(ctx, pts2, major2 ? 0.30 : 0.15);
      if (major2 && Math.abs(lon2) % 30 === 0) {
        var lp2 = findLabelPoint(pts2, w, h, true);
        if (lp2) {
          ctx.fillStyle = 'rgba(140,234,255,.45)';
          ctx.font = '8px "Segoe UI", sans-serif';
          ctx.fillText(Math.abs(lon2) + '°' + (lon2 < 0 ? 'W' : 'E'), lp2.x + 3, h - 3);
        }
      }
    }
  }

  /* 南半球区域强调：光晕 + 60/70/80°S 极圈虚线（视口进入南半球才绘制） */
  function drawSectorEmphasis(map, ctx, w, h) {
    var pole = map.latLngToContainerPoint([-85, 0]);
    if (pole.x < -800 || pole.x > w + 800 || pole.y < -800 || pole.y > h + 800) return;

    var r60 = dist(pole, map.latLngToContainerPoint([-60, 0]));
    var r70 = dist(pole, map.latLngToContainerPoint([-70, 0]));
    var r80 = dist(pole, map.latLngToContainerPoint([-80, 0]));

    /* 区域光晕（微弱，非廉价发光） */
    var g = ctx.createRadialGradient(pole.x, pole.y, 0, pole.x, pole.y, r60);
    g.addColorStop(0, 'rgba(98,217,255,.10)');
    g.addColorStop(0.7, 'rgba(98,217,255,.045)');
    g.addColorStop(1, 'rgba(98,217,255,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(pole.x, pole.y, r60, 0, Math.PI * 2);
    ctx.fill();

    /* 极圈虚线 */
    ctx.setLineDash([6, 4]);
    ctx.strokeStyle = 'rgba(140,234,255,.40)';
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.arc(pole.x, pole.y, r60, 0, Math.PI * 2); ctx.stroke();
    ctx.setLineDash([4, 4]);
    ctx.strokeStyle = 'rgba(140,234,255,.26)';
    ctx.beginPath(); ctx.arc(pole.x, pole.y, r70, 0, Math.PI * 2); ctx.stroke();
    ctx.setLineDash([3, 4]);
    ctx.strokeStyle = 'rgba(140,234,255,.16)';
    ctx.beginPath(); ctx.arc(pole.x, pole.y, r80, 0, Math.PI * 2); ctx.stroke();
    ctx.setLineDash([]);

    ctx.fillStyle = 'rgba(140,234,255,.45)';
    ctx.font = '8px "Segoe UI", sans-serif';
    ctx.fillText('60°S · TEST SECTOR', pole.x + 6, pole.y - r60 - 4);
  }

  /* 站区作业圈：以真实定位点为中心，半径约 300km 的虚线圆 */
  function drawStationZone(map, ctx, w, h) {
    var marker = window.deviceMarker;
    if (!marker) return;
    var ll = marker.getLatLng();
    var p = map.latLngToContainerPoint(ll);
    if (p.x < -500 || p.x > w + 500 || p.y < -500 || p.y > h + 500) return;

    /* 以经度差估算 300km 半径（装饰性量级） */
    var east = map.latLngToContainerPoint([ll.lat, ll.lng + 3.2]);
    var r = dist(p, east);
    if (r < 8 || r > 1400) return;

    ctx.setLineDash([3, 5]);
    ctx.strokeStyle = 'rgba(98,217,255,.22)';
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.arc(p.x, p.y, r, 0, Math.PI * 2); ctx.stroke();
    ctx.setLineDash([]);

    ctx.fillStyle = 'rgba(98,217,255,.4)';
    ctx.font = '8px "Segoe UI", sans-serif';
    ctx.fillText('R≈300KM · ANT-A01 ZONE', p.x + 5, p.y - r - 3);
  }

  /* 将雷达扫掠 / 扩散光圈 / 定位核心移动到真实标记点 */
  function positionOverlays(map) {
    var marker = window.deviceMarker;
    var visible = marker ? 1 : 0;
    if (marker) {
      var p = map.latLngToContainerPoint(marker.getLatLng());
      var x = p.x;
      var y = p.y;
      if (radar) { radar.style.left = x + 'px'; radar.style.top = y + 'px'; }
      if (rings) { rings.style.left = x + 'px'; rings.style.top = y + 'px'; }
      if (core) { core.style.left = x + 'px'; core.style.top = y + 'px'; }
    }
    if (radar) radar.style.opacity = visible;
    if (rings) rings.style.opacity = visible;
    if (core) core.style.opacity = visible;
  }

  /* 统一重绘：网格 + 南半球强调 + 站区圈 + 定位叠层（rAF 节流） */
  function drawMapOverlays() {
    var map = window.deviceMap;
    if (!map || !graticule) return;
    fitCanvas();
    var ctx = graticule.getContext('2d');
    var w = graticule.clientWidth;
    var h = graticule.clientHeight;
    ctx.setTransform(mapDpr, 0, 0, mapDpr, 0, 0);
    drawGraticule(map, ctx, w, h);
    drawSectorEmphasis(map, ctx, w, h);
    drawStationZone(map, ctx, w, h);
    positionOverlays(map);
  }

  function scheduleDraw() {
    if (rafPending) return;
    rafPending = true;
    window.requestAnimationFrame(function () {
      rafPending = false;
      drawMapOverlays();
    });
  }

  /* main.js 异步创建地图，轮询等待其就绪后再挂接重绘事件 */
  function attachToMap() {
    var map = window.deviceMap;
    if (!map) return false;
    map.on('move zoomend resize', scheduleDraw);
    window.addEventListener('resize', scheduleDraw);
    drawMapOverlays();
    return true;
  }
  var tries = 0;
  var poll = setInterval(function () {
    if (attachToMap() || tries++ > 75) clearInterval(poll); // 最长等待约 30 秒
  }, 400);

  /* =========================================================
     3. 状态显示辅助层（纯 DOM 展示逻辑，不影响 main.js 数据刷新）
        - MODE: N/S/E → NORMAL / STANDBY / EMERGENCY + 状态灯颜色
        - NULL: 按设备语义显示 NO SIGNAL / WAITING DATA / NO TELEMETRY / NO FIX
        - 状态灯: 有效=绿 / 等待=黄 / 无信号=红（仅 opacity 呼吸）
  ========================================================= */

  /* MODE 状态映射（N / S / E → 科研设备状态标签） */
  var L = function (k) { return window.ANX_T ? window.ANX_T(k) : k; };
  var MODE_STATES = {
    N:    { labelKey: 'normal',       subKey: 'normal_operation',  cls: 'mode-normal' },
    S:    { labelKey: 'standby',      subKey: 'low_power_standby', cls: 'mode-standby' },
    E:    { labelKey: 'emergency',    subKey: 'protective_mode',   cls: 'mode-emergency' },
    '--': { labelKey: 'waiting_data', subKey: 'mode_unknown',      cls: 'mode-wait' },
    NULL: { labelKey: 'no_signal',    subKey: 'mode_unknown',      cls: 'mode-off' }
  };
  var MODE_CLASSES = ['mode-normal', 'mode-standby', 'mode-emergency', 'mode-wait', 'mode-off'];

  /* 根据 main.js 写入的原始 mode 值渲染状态标签（#systemMode 保留为隐藏原始值） */
  function renderMode() {
    var rawEl = document.getElementById('systemMode');
    var cell = document.getElementById('modeCell');
    var disp = document.getElementById('modeDisplay');
    var sub = document.getElementById('modeSub');
    var mapCell = document.getElementById('mapModeCell');
    var mapVal = document.getElementById('mapModeValue');
    if (!rawEl || !disp) return;
    var raw = (rawEl.textContent || '').trim().toUpperCase();
    if (raw === '') raw = '--';
    var st = MODE_STATES[raw] || MODE_STATES.NULL;
    disp.textContent = L(st.labelKey);
    if (sub) sub.textContent = L(st.subKey);
    if (cell) {
      MODE_CLASSES.forEach(function (c) { cell.classList.remove(c); });
      cell.classList.add(st.cls);
    }
    if (mapVal) mapVal.textContent = L(st.labelKey);
    if (mapCell) {
      MODE_CLASSES.forEach(function (c) { mapCell.classList.remove(c); });
      mapCell.classList.add(st.cls);
    }
  }

  /* 数值空态文案（按设备语义选择，不伪造数据） */
  var VALUE_LABELS = {
    voltage:         'no_signal',
    current:         'no_signal',
    insideTemp:      'no_telemetry',
    outsideTemp:     'no_telemetry',
    humidity:        'no_signal',
    outsideHumidity: 'no_signal',
    solar:           'waiting_data',
    gpsStatusPage:   'no_fix',
    satelliteSmall:  'no_fix',
    satellites:      'no_fix',
    latitude:        'no_fix',
    longitude:       'no_fix'
  };
  var VALUE_IDS = Object.keys(VALUE_LABELS);

  /* 只有主数值控制整卡状态；次级数值（外部温度/湿度/卫星数）只更新自身显示 */
  var CARD_IDS = {
    voltage: 1, current: 1, insideTemp: 1, humidity: 1, solar: 1, gpsStatusPage: 1
  };

  function refreshValue(el, id) {
    if (!el) return;
    var txt = (el.textContent || '').trim();
    var state;
    var label;
    var key;

    /* 若当前文字仍是本层渲染的占位文案，保持原状态（避免自触发死循环） */
    if (el.dataset.state && txt === (el.dataset.label || '')) {
      state = el.dataset.state;
      key = el.dataset.key || '';
      label = state === 'ok' ? '' : L(key);
    } else if (txt === '--' || txt === '') {
      state = 'wait';
      key = 'waiting_data';
      label = L(key);
    } else if (/^null$/i.test(txt) || txt === (window.ANX_T ? window.ANX_T('null') : 'NULL')) {
      state = 'off';
      key = VALUE_LABELS[id] || 'no_signal';
      label = L(key);
    } else {
      state = 'ok';
      key = '';
      label = '';
    }

    var card = CARD_IDS[id] ? el.closest('.sensor-card') : null;
    if (card) {
      card.classList.toggle('st-wait', state === 'wait');
      card.classList.toggle('st-off', state === 'off');
      card.classList.toggle('st-ok', state === 'ok');
      var chip = card.querySelector('.sensor-state');
      if (chip) {
        chip.textContent = state === 'ok' ? L('nominal') : (state === 'wait' ? L('awaiting_sensor') : L('sensor_offline'));
      }
    }

    el.classList.remove('st-wait', 'st-off', 'st-ok');
    if (label) {
      if (el.textContent !== label) el.textContent = label;
      el.dataset.state = state;
      el.dataset.key = key;
      el.dataset.label = label;
      el.classList.add('st-' + state);
    } else {
      delete el.dataset.state;
      delete el.dataset.label;
    }
  }

  function syncStatus() {
    renderMode();
    VALUE_IDS.forEach(function (id) { refreshValue(document.getElementById(id), id); });
  }

  syncStatus();
  if (window.addEventListener) {
    window.addEventListener('anx:langchange', function () { syncStatus(); });
  }
  if (window.MutationObserver) {
    var statusObserver = new MutationObserver(syncStatus);
    var statusIds = VALUE_IDS.concat(['systemMode']);
    statusIds.forEach(function (id) {
      var el = document.getElementById(id);
      if (el) statusObserver.observe(el, { childList: true, subtree: true, characterData: true });
    });
  }
})();



  (function () {
    function apply(lang) {
      document.documentElement.setAttribute('data-lang', lang);
      document.documentElement.setAttribute('lang', lang === 'zh' ? 'zh-CN' : 'en');
      document.querySelectorAll('[data-lang]').forEach(function (el) {
        if (el.tagName === 'BUTTON' && el.parentNode && el.parentNode.classList && el.parentNode.classList.contains('lang-switch')) return;
        el.style.display = (el.getAttribute('data-lang') === lang) ? '' : 'none';
      });
      document.querySelectorAll('.lang-switch button').forEach(function (b) {
        var on = b.getAttribute('data-lang') === lang;
        b.classList.toggle('active', on);
        if (b.hasAttribute('aria-pressed')) b.setAttribute('aria-pressed', String(on));
      });
      try { localStorage.setItem('anx-lang', lang); } catch (e) {}
      window.anxCurrentLang = lang;
      window.anxApplyLang = apply;
      var titleEl = document.querySelector('title');
      if (titleEl) {
        var tEn = titleEl.getAttribute('data-title-en');
        var tZh = titleEl.getAttribute('data-title-zh');
        if (tEn && tZh) titleEl.textContent = lang === 'zh' ? tZh : tEn;
      }
      if (window.ANX_APPLY_I18N) window.ANX_APPLY_I18N(lang);
      try { window.dispatchEvent(new CustomEvent('anx:langchange', { detail: { lang: lang } })); } catch (e) {}
    }
    function bind() {
      document.querySelectorAll('.lang-switch button').forEach(function (b) {
        b.addEventListener('click', function (ev) {
          ev.preventDefault();
          apply(b.getAttribute('data-lang'));
        });
      });
    }
    var saved = null;
    try { saved = localStorage.getItem('anx-lang'); } catch (e) {}
    apply(saved === 'zh' ? 'zh' : 'en');
    bind();
  })();
